/// Number of bytes required to hold `bits` bits.
constexpr int64_t bytesForBits(int64_t bits)
{
    return (bits + 7) >> 3;
}

/// Size of a buffer treating an absent (null) buffer as zero bytes. ClickHouse's Arrow
/// readers legitimately handle a missing value-data buffer when every value is empty
/// (the IPC body may omit an all-empty values buffer), so we must not hard-reject it.
int64_t optionalBufferSize(const arrow::ArrayData & data, size_t index)
{
    if (index >= data.buffers.size() || data.buffers[index] == nullptr)
        return 0;
    return static_cast<int64_t>(data.buffers[index]->size());
}

/// Whether the row at logical position `i` is null according to the validity bitmap.
/// The bitmap must have been size-validated before calling this.
bool isNullInBitmap(const arrow::ArrayData & data, int64_t i)
{
    if (data.buffers.empty() || data.buffers[0] == nullptr)
        return false;
    const auto * bitmap = data.buffers[0]->data();
    if (!bitmap)
        return false;
    const int64_t bit = data.offset + i;
    return (bitmap[bit >> 3] & (1u << (bit & 7))) == 0;
}

template <typename T>
T loadLittleEndian(const uint8_t * p)
{
    T v;
    memcpy(&v, p, sizeof(T));
    return v;
}

